/* Manage Action's left-side suggestion/evidence panel; execution fields stay on the right. */
(()=>{
let current=null;
state.taskGuidanceDrafts??={};
const scope=(d,t,visitId)=>d.patientId+'|'+(visitId||'device')+'|'+t.id;
function panel(d,t,visitId=''){
 const card=FNTaskGuidance.build(d,t),saved=state.taskGuidanceDrafts[scope(d,t,visitId)]||t.justification;let selected;try{selected=FNTaskGuidance.resolve(card,saved||{})}catch{selected=FNTaskGuidance.resolve(card,{})}current={card,selected,scope:scope(d,t,visitId)};
 const o=card.order;
 return `<aside class="task-guidance" aria-label="Suggested action and evidence"><section class="task-suggestion-box"><span class="intake-eyebrow">SUGGESTED ACTION</span><h3>${esc(card.title)}</h3><p class="task-suggestion-main">${esc(card.suggestedAction)}</p><div class="task-context"><span>${esc(d.patientId)}</span><span>${esc(d.current.risk)}</span></div>${o?`<div class="task-regimen-preview">${o.items.length?o.items.map(m=>`<article><b>${esc(m.name)}</b><p><strong>Initial:</strong> ${esc(m.initialDose)}<br><strong>Route:</strong> ${esc(m.route)} · ${esc(m.administration)}</p><details><summary>Repeat-dose reference & monitoring</summary><p>${esc(m.repeatDose)}</p><p>${esc(m.renalContext)}</p><p>${esc(m.monitoring)}</p></details></article>`).join(''):'<p>No new initial dose suggested. Review ongoing therapy or missing safety information.</p>'}${o.holds.length?`<div class="task-guidance-holds"><b>Review required</b>${o.holds.map(h=>`<p>${esc(h)}</p>`).join('')}</div>`:''}</div>`:''}<p class="mini">Suggestion only · selecting it does not complete the task or approve treatment.</p></section><section class="task-evidence-box"><span class="intake-eyebrow">EVIDENCE RULE</span><div class="task-rule-heading"><b>${esc(card.ruleId)}</b><span>Suggested</span></div><p class="mini">${esc(card.ruleContext)}</p><h4>Why this action?</h4>${card.rationale.map(r=>`<label class="task-guidance-choice"><input type="checkbox" data-task-r="${esc(r.id)}" ${selected.rationaleIds.includes(r.id)?'checked':''} onchange="fnTaskGuidance.choose()"><span>${esc(r.text)}</span></label>`).join('')}<h4>Supporting evidence</h4>${card.references.length?card.references.map(r=>`<label class="task-guidance-choice"><input type="checkbox" data-task-e="${esc(r.id)}" ${selected.evidenceIds.includes(r.id)?'checked':''} onchange="fnTaskGuidance.choose()"><span><b>${esc(r.title)}</b><small>${esc(r.version||'Drug-specific reference')} · ${esc(r.location||'See dosing source')}</small><a href="${esc(r.url)}" target="_blank" rel="noopener">Read evidence ↗</a></span></label>`).join(''):'<p class="mini">Clinician-defined task. Record the specific source in your evidence note; no clinical guideline match is assumed.</p>'}<p id="task-guidance-status" role="status">${selected.complete?'Reviewed selections available for this task.':'Choose the rationale and the evidence that support your decision.'}</p><button class="btn" type="button" onclick="fnTaskGuidance.useNote()">Use selected rationale in evidence note →</button><p class="mini">Selections are saved with this task action. Clinical role and treatment-review checks still apply.</p></section></aside>`;
}
function choose(){if(!current)return;const root=document.querySelector('.task-guidance'),raw={signature:current.card.signature,rationaleIds:[...root.querySelectorAll('[data-task-r]:checked')].map(x=>x.dataset.taskR),evidenceIds:[...root.querySelectorAll('[data-task-e]:checked')].map(x=>x.dataset.taskE)};current.selected=FNTaskGuidance.resolve(current.card,raw);state.taskGuidanceDrafts[current.scope]=raw;let status=current.selected.complete?'Selections ready to save with this action.':'Choose a supporting reference for the selected rationale.';try{localStorage.setItem('fn-demo-v1',JSON.stringify(state))}catch{status='Device storage unavailable; save the task action before leaving.'}document.querySelector('#task-guidance-status').textContent=status}
function payload(){if(!current||!current.selected.rationaleIds.length&&!current.selected.evidenceIds.length)return null;const s=FNTaskGuidance.resolve(current.card,current.selected,true);return {signature:s.signature,rationaleIds:s.rationaleIds,evidenceIds:s.evidenceIds}}
function useNote(){try{const raw=payload();if(!raw)throw Error('Choose a suggested rationale first.');const field=document.querySelector('#dyn-form [name="note"]'),suggested=FNTaskGuidance.note(current.selected);if(field.value.includes(suggested)){field.focus();return}const next=(field.value.trim()?field.value.trim()+'\n\n':'')+suggested;if(next.length>800)throw Error('The combined note is too long. Shorten the note or select fewer references.');field.value=next;field.focus();document.querySelector('#task-guidance-status').textContent='Copied to the evidence note. Review it and document what actually happened.'}catch(e){document.querySelector('#task-guidance-status').textContent=e.message}}
window.fnTaskGuidance={panel,choose,payload,useNote};
})();
